for i, (prompt, options, answer, explanation, strategy) in enumerate(DATA, 1):
    path = ROOT / "questions/science" / f"question-science-content-md-iv-1-{i}.json"
    item = json.loads(path.read_text())
    correct = options[ord(answer) - 65]
    target = TARGET_ANSWERS[i - 1]
    distractors = [text for option_index, text in enumerate(options) if option_index != ord(answer) - 65]
    position = ord(target) - 65
    arranged = distractors[:position] + [correct] + distractors[position:]
    item.update({"prompt": prompt, "options": [{"id": chr(65+j), "text": t} for j, t in enumerate(arranged)], "answer": {"value": target, "explanation": f"{explanation} 正確答案為選項 {target}：「{correct}」。"}, "solutionStrategy": strategy, "solutionSteps": ["圈出災害類型、自然條件、人類行動、受影響生物與可量化指標。", "檢查是否有歷史資料、空間對照、風險分層與復育後追蹤。", f"套用本題原理：{explanation}", f"排除只看單次外觀、忽略人身安全或只追求單一效益的選項，答案為「{correct}」（選項 {target}）。", "回查方案是否同時兼顧減災、保育、社區需求與後續調整。"], "examPatternRefs": REFS, "reviewStatus": "draft", "updatedAt": "2026-09-13"})
